import json

# Normalize Apify output into a consistent format
items = {{$json}}
if isinstance(items, dict):
    items = items.get('results', items.get('data', [items]))
if not isinstance(items, list):
    items = [items]

normalized = []
for job in items:
    normalized.append({
        'company': job.get('companyName') or job.get('company') or '',
        'title': job.get('title') or job.get('jobTitle') or job.get('name') or '',
        'location': job.get('location') or job.get('locations') or '',
        'experience': job.get('experienceRequired') or job.get('experience') or '',
        'job_url': job.get('url') or job.get('jobUrl') or job.get('link') or '',
        'jd': job.get('description') or job.get('body') or job.get('text') or '',
        'source': 'apify',
        'posted_date': job.get('postedDate') or job.get('date') or ''
    })

return normalized

import json

analysis = {{$json}}
choices = analysis.get('choices', [])
if not choices:
    return {'error': 'No analysis result', 'overall_score': 0, 'recommended': False}

try:
    result = json.loads(choices[0].get('message', {}).get('content', '{}'))
except Exception:
    return {'error': 'Failed to parse LLM output', 'overall_score': 0, 'recommended': False}

if result.get('experience_status') == 'REJECT':
    result['overall_score'] = -1
    result['recommended'] = False

return result
